function calcBreakEven(){const fixed=n("fixed"),price=n("sell"),variable=n("variable");if(!Number.isFinite(fixed)||!Number.isFinite(price)||!Number.isFinite(variable)||fixed<0||price<0||variable<0||price<=variable){$("result").textContent="Enter valid costs. Selling price must be greater than variable cost.";return}const units=fixed/(price-variable),revenue=units*price;if(!Number.isFinite(units)||!Number.isFinite(revenue)){$("result").textContent="These values are too large for a reliable result.";return}$("result").innerHTML="<strong>"+units.toFixed(2)+" units</strong><br>Break-even revenue: "+revenue.toFixed(2)}


