async function imageCompress(){const files=imageFiles("compressor"),quality=Number($("imgQuality")?.value),selected=$("imgOutputFormat")?.value||"auto";if(!files.length){$("result").textContent="Choose one or more images first.";return}if(!Number.isFinite(quality)||quality<.1||quality>1){$("result").textContent="Choose a quality between 10% and 100%.";return}const results=[],totalBefore=files.reduce(function(sum,f){return sum+f.size},0);$("result").textContent="Compressing "+files.length+" image"+(files.length===1?"":"s")+"…";for(const file of files){try{if(file.size>IMAGE_MAX_BYTES)throw new Error("File exceeds the 25 MB limit.");const d=await imageLoadDimensions(file);if(d.width>IMAGE_MAX_DIMENSION||d.height>IMAGE_MAX_DIMENSION)throw new Error("Image dimensions exceed 16,384 px.");const type=imageOutputType(file.type,selected);const canvas=document.createElement("canvas");canvas.width=d.width;canvas.height=d.height;const ctx=canvas.getContext("2d");if(!ctx)throw new Error("Canvas processing is unavailable in this browser.");if(type==="image/jpeg"){ctx.fillStyle=$("imgBackground")?.value||"#ffffff";ctx.fillRect(0,0,d.width,d.height)}const loaded=await loadImage(file);ctx.drawImage(loaded.im,0,0,d.width,d.height);const blob=await imageEncode(canvas,type,quality);if(blob.type!==type)throw new Error("This browser could not create "+imageFormatName(type)+" output.");const base=imageSafeName(file.name).replace(/\.[^.]+$/,"");results.push({name:file.name,before:file.size,blob:blob,width:d.width,height:d.height,outputName:base+"."+imageExtension(type)})}catch(e){results.push({name:file.name,before:file.size,error:e.message||"Could not process image."})}}imageRenderResult("compressor",results,totalBefore)}
