function calcBusinessDays(){const a=$("bdStart").value,b=$("bdEnd").value;if(!a||!b){$("result").textContent="Enter both dates.";return}let s=parseIsoDate(a),e=parseIsoDate(b);if(!s||!e){$("result").textContent="Enter valid dates.";return}if(s>e){const t=s;s=e;e=t}const days=Math.floor((e-s)/86400000)+1,fullWeeks=Math.floor(days/7),remainder=days%7,startDay=s.getUTCDay();let count=fullWeeks*5;for(let i=0;i<remainder;i++){const day=(startDay+i)%7;if(day!==0&&day!==6)count++}$("result").innerHTML="<strong>"+count+" weekdays</strong><br>Public holidays are not excluded."}

function randomNumber(){return '<h2>Random Number Generator</h2><p class="note">Generate a cryptographically strong random integer in your browser.</p><div class="form"><label>Minimum<input id="rndMin" type="number" value="1"></label><label>Maximum<input id="rndMax" type="number" value="100"></label><button type="button" data-action=\"generateRandom\">Generate</button></div><div id="result" class="result"></div>'}
function generateRandom(){const min=Number(el("rndMin").value),max=Number(el("rndMax").value),r=el("result");if(!Number.isSafeInteger(min)||!Number.isSafeInteger(max)||min>max){r.textContent="Enter whole numbers with minimum no greater than maximum.";return}if(!window.crypto||typeof crypto.getRandomValues!=="function"){r.textContent="Secure random generation is not available in this browser.";return}const range=BigInt(max)-BigInt(min)+1n;if(range<=0n||range>4294967296n){r.textContent="Use a range of up to 4,294,967,296 possible integers.";return}const limit=4294967296n-(4294967296n%range),buf=new Uint32Array(1);let x;do{crypto.getRandomValues(buf);x=BigInt(buf[0])}while(x>=limit);r.innerHTML='<strong>'+ (BigInt(min)+(x%range)).toString() +'</strong>'}
function aspectRatio(){return '<h2>Aspect Ratio Calculator</h2><div class="form"><label>Width<input id="arw" type="number" value="1920"></label><label>Height<input id="arh" type="number" value="1080"></label><button type="button" data-action=\"calcAspect\">Calculate</button></div><div id="result" class="result"></div>'}
