function timestampToDate(){const v=Number(el("ts").value),unit=el("tsUnit").value,r=el("result");if(!["seconds","milliseconds","auto"].includes(unit)){r.textContent="Choose a supported timestamp unit.";return}if(!Number.isSafeInteger(v)){r.textContent="Enter a whole-number timestamp within the supported safe range.";return}const ms=unit==="milliseconds"?v:unit==="auto"?(Math.abs(v)>=100000000000?v:v*1000):v*1000;if(!Number.isSafeInteger(ms)){r.textContent="Timestamp is outside the supported safe range.";return}const d=new Date(ms);if(Number.isNaN(d.getTime())){r.textContent="Timestamp is outside the supported date range.";return}r.textContent=d.toISOString()}
function dateToTimestamp(){const v=el("dt").value,r=el("result");if(!v){r.textContent="Choose a date and time.";return}const d=new Date(v);if(Number.isNaN(d.getTime())){r.textContent="Enter a valid date and time.";return}r.textContent=Math.floor(d.getTime()/1000).toString()}
function base64(){return '<h2>Base64 Encoder & Decoder</h2><div class="form"><label>Text<textarea id="b64" rows="7" placeholder="Enter text"></textarea></label><button type="button" data-action=\"encodeBase64\">Encode</button><button type="button" data-action=\"decodeBase64\">Decode</button></div><div id="result" class="result"></div>'}
function encodeBase64(){const s=el("b64").value,r=el("result");try{const bytes=new TextEncoder().encode(s);let bin="";bytes.forEach(b=>bin+=String.fromCharCode(b));r.textContent=btoa(bin)}catch(e){r.textContent="Could not encode this text."}}
function decodeBase64(){const s=el("b64").value.trim(),r=el("result");try{const bin=atob(s),bytes=Uint8Array.from(bin,c=>c.charCodeAt(0));r.textContent=new TextDecoder("utf-8",{fatal:true}).decode(bytes)}catch(e){r.textContent="Invalid Base64 input."}}


function quotePulseExample(){
  const example = "Site visit $50\nLabour $480\nMaterials $620\nDeposit 60%\nTotal $1150\n12-month warranty";
  const field = el("quoteText");
  if(field){field.value=example}
}
function analyzeQuote(){
  const raw = (el("quoteText")?.value || "").trim();
  const r = el("result"), msg = el("qpMessage");
  if(!raw){r.textContent="Paste a quote or estimate first.";if(msg)msg.hidden=true;return}
  const lines = raw.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
  const amountRe = /(?:[$€£₹]\s*|\b(?:USD|EUR|GBP|INR|CAD|AUD)\s*)?(\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+(?:\.\d+)?)(?!\s*%)/gi;
  const lineItems = [];
  let statedTotal = null, depositPercent = null, depositAmount = null;
  const lower = raw.toLowerCase();
  lines.forEach(line=>{
    const l=line.toLowerCase();
    const percentMatch=l.match(/(?:deposit|down payment|upfront)[^\d%]*(\d+(?:\.\d+)?)\s*%/i);
    if(percentMatch) depositPercent=Number(percentMatch[1]);
    const isTotal=/\b(?:grand total|total|amount due|balance due)\b/i.test(line);
    const isDeposit=/\b(?:deposit|down payment|upfront)\b/i.test(line);
    const totalMatch=line.match(/\b(?:grand total|total|amount due|balance due)\b[^\d$€£₹]{0,24}[$€£₹]?\s*([\d,]+(?:\.\d+)?)/i);
    if(totalMatch) statedTotal=Number(totalMatch[1].replace(/,/g,""));
    const matches=[...line.matchAll(amountRe)];
    if(matches.length){
      const m=matches[matches.length-1];
      const value=Number(m[1].replace(/,/g,""));
      const hasPercent=/%/.test(line.slice(Math.max(0,m.index-8), Math.min(line.length,m.index+m[0].length+8)));
      const dateLike=/\b20\d{2}[-/]\d{1,2}[-/]\d{1,2}\b/.test(line);
      const durationLike=/\b\d+(?:\.\d+)?\s*(?:second|seconds|sec|secs|minute|minutes|min|mins|hour|hours|hr|hrs|day|days|week|weeks|month|months|year|years)\b/i.test(line);
      const quantityLike=/\b\d+(?:\.\d+)?\s*(?:item|items|unit|units|piece|pieces|pcs|qty|quantity)\b/i.test(line);
      if(Number.isFinite(value)&&value>=0&&!hasPercent&&!dateLike&&!durationLike&&!quantityLike&&!isTotal&&!isDeposit){
        let label=line.slice(0,m.index).replace(/[-:|•]+\s*$/,"").trim();
        label=label.replace(/^(item|description|service|line)\s*[:#-]?\s*/i,"").trim();
        if(label.length>1) lineItems.push({label,value});
      } else if(isDeposit&&Number.isFinite(value)&&value>0){depositAmount=value}
    }
  });
  const flags=[];
  if(statedTotal===null) flags.push({type:"watch",text:"No explicit total was detected. Ask for the final amount including taxes, fees, and extras."});
  if(lineItems.length===0) flags.push({type:"watch",text:"No clear line-item amounts were detected. Ask for an itemized breakdown."});
  if(depositPercent!==null){
    if(depositPercent>50) flags.push({type:"risk",text:"The stated deposit is above 50%. Confirm what is refundable and what happens if the job is cancelled."});
    else if(depositPercent>30) flags.push({type:"watch",text:"The quote asks for more than 30% upfront. Check payment milestones and refund terms."});
  } else if(depositAmount!==null&&statedTotal>0){
    depositPercent=depositAmount/statedTotal*100;
    if(depositPercent>50) flags.push({type:"risk",text:"The detected deposit is above 50% of the stated total. Confirm refund and cancellation terms."});
  }
  if(/\b(misc|miscellaneous|other|sundries|etc\.?|tbd|allowance|provisional|as required|contingency)\b/i.test(raw))
    flags.push({type:"watch",text:"Vague scope wording was detected. Ask exactly what is included, excluded, and billable as a change order."});
  if(!/\b(warranty|guarantee)\b/i.test(lower))
    flags.push({type:"watch",text:"No warranty or guarantee language was detected. Ask for duration, coverage, and exclusions."});
  if(!/\b(change order|variation|extra work|additional work|scope change)\b/i.test(lower))
    flags.push({type:"watch",text:"No change-order rule was detected. Ask how extra work is approved and priced."});
  if(!/\b(cancel|cancellation|refund|refundable)\b/i.test(lower))
    flags.push({type:"watch",text:"No cancellation or refund terms were detected."});
  if(!/\b(tax|vat|gst|sales tax|service tax|fees?)\b/i.test(lower))
    flags.push({type:"watch",text:"Taxes or fees are not mentioned. Confirm whether the quoted total is all-in."});
  if(statedTotal!==null&&lineItems.length){
    const sum=lineItems.reduce((a,x)=>a+x.value,0);
    const diff=sum-statedTotal, relative=statedTotal?Math.abs(diff)/statedTotal:0;
    if(relative>0.01) flags.push({type:"risk",text:"The detected line items do not reconcile with the stated total. Ask for the exact source of the difference."});
  }
  const counts={};
  lineItems.forEach(x=>{
    const key=x.label.toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
    if(key) counts[key]=(counts[key]||0)+1;
  });
  const duplicateLabels=Object.keys(counts).filter(k=>counts[k]>1);
  if(duplicateLabels.length) flags.push({type:"watch",text:"Duplicate-looking line items were detected. Ask whether they are separate charges or accidental repeats."});
  let score=100;
  flags.forEach(f=>score-=f.type==="risk"?15:8);
  if(score<20) score=20;
  const level=score>=80?"Clear":score>=60?"Needs questions":"Needs careful review";
  const itemSum=lineItems.reduce((a,x)=>a+x.value,0);
  const currencyHint=(raw.match(/[$€£₹]|\b(?:USD|EUR|GBP|INR|CAD|AUD)\b/i)||[""])[0];
  const fmtMoney=v=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:2}):"n/a";
  const flagHtml=flags.length?flags.map((f,i)=>'<div class="quote-flag '+esc(f.type)+'"><div class="quote-flag-marker" aria-hidden="true">'+esc(f.type==="risk"?"!":"?")+'</div><div><div class="quote-flag-meta">'+esc(f.type==="risk"?"Review":"Check")+' <span>Issue '+(i+1)+'</span></div><p>'+esc(f.text)+'</p></div></div>').join(""):'<div class="quote-good"><strong>No obvious document-level red flags were detected.</strong><span>The quote passed the document-level checks currently supported by QuotePulse.</span></div>';
  const itemsHtml=lineItems.slice(0,12).map((x,i)=>'<div class="quote-row"><span class="quote-item-index">'+(i+1)+'</span><span class="quote-item-label">'+esc(x.label)+'</span><b>'+esc(currencyHint)+' '+fmtMoney(x.value)+'</b></div>').join("");
  r.innerHTML='<div class="quote-summary"><div class="quote-score-card"><div><span class="quote-metric-label">Clarity score</span><strong>'+score+'<small>/100</small></strong><span class="quote-status">'+esc(level)+'</span></div><p>Based on the document-level checks found in this quote.</p></div><div class="quote-metric"><span>Line items</span><strong>'+lineItems.length+'</strong><small>detected</small></div><div class="quote-metric"><span>Stated total</span><strong>'+(statedTotal!==null?esc(currencyHint)+' '+fmtMoney(statedTotal):"Not found")+'</strong><small>from text</small></div><div class="quote-metric"><span>Detected item sum</span><strong>'+(lineItems.length?esc(currencyHint)+' '+fmtMoney(itemSum):"Not found")+'</strong><small>before non-item lines</small></div></div><section class="quote-section" aria-labelledby="quote-checks-heading"><div class="quote-section-heading"><div><span class="quote-section-kicker">Review</span><h3 id="quote-checks-heading">What needs attention</h3></div><span class="quote-count">'+flags.length+' '+(flags.length===1?"item":"items")+'</span></div>'+flagHtml+'</section>'+(itemsHtml?'<section class="quote-section" aria-labelledby="quote-items-heading"><div class="quote-section-heading"><div><span class="quote-section-kicker">Breakdown</span><h3 id="quote-items-heading">Detected line items</h3></div><span class="quote-count">'+lineItems.length+' detected</span></div><div class="quote-list">'+itemsHtml+'</div></section>':"")+'<div class="quote-disclaimer"><strong>Use this as a question generator, not a price verdict.</strong><span>QuotePulse checks document completeness and arithmetic patterns. It does not know local market prices and does not replace professional, legal, financial or trade advice.</span></div>';
  if(msg){
    const questions=[
      "Can you confirm exactly what is included and excluded in each line item?",
      "Is the quoted total final, including taxes, fees, delivery, permits, and expected extras?",
      depositPercent!==null?"What happens to the deposit if the work is cancelled or scope changes?":"What are the payment milestones and refund terms?",
      "What warranty or guarantee is included, and for how long?",
      "How are extra or change-order costs approved before they are billed?"
    ];
    msg.hidden=false;
    msg.innerHTML='<div class="quote-message-head"><div><span class="quote-section-kicker">Ready to send</span><h3>Negotiation message</h3><p>Ask for the missing details before you approve the quote.</p></div><span class="quote-message-badge">'+questions.length+' questions</span></div><div class="quote-message-body"><p>Hi, thanks for the quote. Before I approve it, could you please confirm the following?</p><ol>'+questions.map((q,i)=>'<li><span>'+(i+1)+'</span><p>'+esc(q)+'</p></li>').join("")+'</ol><p>Once I have those details, I can review the scope and payment terms clearly.</p></div><div class="quote-message-actions"><button type="button" data-action="copyQuoteMessage">Copy message</button><span class="note">Edit the message to match your situation before sending.</span></div>';
    const messageText="Hi, thanks for the quote. Before I approve it, could you please confirm the following?\n\n"+questions.map((q,i)=>(i+1)+". "+q).join("\n")+"\n\nOnce I have those details, I can review the scope and payment terms clearly.";
    if(msg.dataset) msg.dataset.message=messageText;
  }
}
function copyQuoteMessage(){
  const box=el("qpMessage"),text=box?.dataset?.message||"";
  if(!text)return;
  if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(()=>{box.insertAdjacentHTML("beforeend",'<p class="note">Copied.</p>')}).catch(()=>{prompt("Copy this message:",text)})}
  else prompt("Copy this message:",text);
}



const toolActions=Object.freeze({calcPercentage,calcDiscount,calcLoan,calcInterest,calcAge,calcChange,calcTip,calcBmi,calcDate,calcConvert,calcText,formatJson,convertCase,generatePassword,calcDuration,calcBusinessDays,calcCompound,calcMargin,calcRoi,calcBreakEven,imageCompress,imageResize,imageConvert,generateRandom,calcAspect,timestampToDate,dateToTimestamp,analyzeQuote,quotePulseExample,print:()=>window.print(),encodeBase64,decodeBase64,copyQuoteMessage,pickResizerFiles:()=>$("resizeFile")?.click(),pickCompressorFiles:()=>$("imgFile")?.click(),pickConverterFiles:()=>$("convertFile")?.click(),clearImageResizer:()=>imageSetFiles("resizer",[]),clearImageCompressor:()=>imageSetFiles("compressor",[]),clearImageConverter:()=>imageSetConverterFiles([])});

document.addEventListener("click",event=>{const button=event.target.closest("[data-action]");if(!button)return;const action=button.dataset.action;const fn=toolActions[action];if(typeof fn==="function")fn();});
document.addEventListener("change",event=>{const id=event.target.id;if(id==="resizeFile")imageSetFiles("resizer",event.target.files);else if(id==="imgFile")imageSetFiles("compressor",event.target.files);else if(id==="convertFile")imageSetConverterFiles(event.target.files);else if(id==="resizeMode"){imageUpdateResizeMode();imageUpdateResizeEstimate()}else if(id==="resizeCropMode"){imageUpdateResizeMode();imageUpdateResizeEstimate()}else if(["resizeWidth","resizeHeight","resizeScale","resizeLock","resizeCropX","resizeCropY","resizeCropWidth","resizeCropHeight"].includes(id))imageUpdateResizeEstimate();else if(id==="resizeQuality"){const out=$("resizeQualityValue");if(out)out.value=Math.round(Number(event.target.value)*100)+"%"}else if(id==="imgQuality"){const out=$("imgQualityValue");if(out)out.value=Math.round(Number(event.target.value)*100)+"%"}else if(id==="convertQuality"){const out=$("convertQualityValue");if(out)out.value=Math.round(Number(event.target.value)*100)+"%"}});
document.addEventListener("click",event=>{const zone=event.target.closest(".image-dropzone");if(zone){const input=$(zone.id==="resizeDropzone"?"resizeFile":zone.id==="compressDropzone"?"imgFile":"convertFile");if(input)input.click()}});
["resizeDropzone","compressDropzone","convertDropzone"].forEach(function(id){const zone=$(id);if(!zone)return;zone.addEventListener("keydown",function(event){if(event.key!=="Enter"&&event.key!==" ")return;event.preventDefault();const input=$(id==="resizeDropzone"?"resizeFile":id==="compressDropzone"?"imgFile":"convertFile");if(input)input.click()})});
["resizeDropzone","compressDropzone","convertDropzone"].forEach(function(id){const zone=$(id);if(!zone)return;zone.addEventListener("dragover",function(event){event.preventDefault();zone.classList.add("is-dragging")});zone.addEventListener("dragleave",function(){zone.classList.remove("is-dragging")});zone.addEventListener("drop",function(event){event.preventDefault();zone.classList.remove("is-dragging");id==="resizeDropzone"?imageSetFiles("resizer",event.dataTransfer?.files||[]):id==="compressDropzone"?imageSetFiles("compressor",event.dataTransfer?.files||[]):imageSetConverterFiles(event.dataTransfer?.files||[])})});